<script setup lang="ts">const p=defineProps<{product:any}>(),{media,api,token}=useShopApi(),{toggle,has}=useCompare();const liked=ref(false),variant=computed(()=>p.product.variants?.[0]),money=(v=0)=>new Intl.NumberFormat('fa-IR').format(v);async function favorite(){if(!token.value)return navigateTo('/login');const r=await api<any>(`/favorites/${p.product.id}`,{method:'POST'});liked.value=r.is_favorite}</script>
<template><article class="group relative overflow-hidden rounded-2xl border border-stone-200 bg-white transition hover:-translate-y-1 hover:shadow-soft"><NuxtLink :to="`/products/${product.slug}`" class="block"><div class="relative aspect-square overflow-hidden bg-stone-100"><img v-if="product.media?.[0]" :src="media(product.media[0].path)" :alt="product.title" class="size-full object-cover transition duration-500 group-hover:scale-105"><div v-else class="grid size-full place-items-center text-5xl text-stone-300">◇</div><span v-if="variant?.compare_at_price>variant?.price" class="absolute right-3 top-3 rounded-lg bg-rose-600 px-2 py-1 text-xs font-bold text-white">ویژه</span></div><div class="p-4"><h3 class="min-h-12 text-sm font-bold leading-6">{{product.title}}</h3><div class="mt-4 flex items-end justify-between"><span class="text-xs text-slate-400">{{variant?.stock?'موجود':'ناموجود'}}</span><div class="text-left"><del v-if="variant?.compare_at_price" class="block text-xs text-slate-400">{{money(variant.compare_at_price)}}</del><p class="font-black text-brand-900">{{money(variant?.price)}} <span class="text-xs">تومان</span></p></div></div></div></NuxtLink><div class="absolute left-3 top-3 flex gap-2"><button :class="['grid size-9 place-items-center rounded-full bg-white shadow',liked?'text-rose-600':'text-slate-500']" title="علاقه‌مندی" @click="favorite">{{liked?'♥':'♡'}}</button><button :class="['grid size-9 place-items-center rounded-full bg-white text-xs font-bold shadow',has(product.id)?'text-brand-700':'text-slate-500']" title="مقایسه" @click="toggle(product.id)">⇄</button></div></article></template>
